  const imgs = {};
  function img(n) { let im = imgs[n]; if (!im) { im = imgs[n] = new Image(); im.decoding = 'async'; im.src = uri(n); } return im; }
  function split(s) { const out = []; let last = 0, m; re.lastIndex = 0; while ((m = re.exec(s))) { if (m.index > last) out.push({ t: s.slice(last, m.index) }); out.push({ n: EMO_MAP[m[1]], e: m[0] }); last = m.index + m[0].length; } if (last < s.length) out.push({ t: s.slice(last) }); return out; }

  /* canvas */
