      if (typeof str !== 'string' || !has.test(str)) return mw === undefined ? orig.call(this, str, x, y) : orig.call(this, str, x, y, mw);
      const px = parseFloat((/(\d+(?:\.\d+)?)px/.exec(this.font) || [0, 14])[1]), s = px * 1.18, parts = split(str);
      let W = 0; for (const p of parts) { p.w = p.n ? s : this.measureText(p.t).width; W += p.w; }
      const al = this.textAlign, bl = this.textBaseline;
      let cx = al === 'center' ? x - W / 2 : (al === 'right' || al === 'end') ? x - W : x;
      const top = bl === 'middle' ? y - s / 2 : (bl === 'top' || bl === 'hanging') ? y - s * .06 : (bl === 'bottom' || bl === 'ideographic') ? y - s : y - s * .84;
      this.textAlign = 'left';
